// Generated by scripts/sync-valuation.py from shared/valuation/weights.js as rp-valuation-weights.js; edit the shared source.
// Shared yield-weight primitives. Pure ES module: no game globals, no I/O.
// Legacy models delegate their arithmetic here so the weighting loop has one
// source of truth; their historical weight tables stay in their own modules.

export const YIELD_KEYS = Object.freeze([
  'food', 'production', 'gold', 'science', 'culture', 'happiness', 'diplomacy'
]);

// Explicit heuristic defaults for the new model. Gold is the unit of account.
// culture=2 is an adjustable assumption, not an official game rule. Happiness
// and diplomacy are not silently priced here: they have dedicated models.
export const DEFAULT_VALUATION_WEIGHTS = Object.freeze({
  food: 2,
  production: 2,
  gold: 1,
  science: 2,
  culture: 2,
  happiness: 0,
  diplomacy: 0
});

export const MIN_WEIGHT = 0;
export const MAX_WEIGHT = 100;

export function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

export function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

// Basic weighted arithmetic. This intentionally mirrors the legacy reduce()
// loops and does not validate; callers that need rejection use scoreYields().
export function weightedSum(terms) {
  let total = 0;
  for (const [value, weight] of terms) total += value * weight;
  return total;
}

export function normalizeWeight(value, fallback = 0) {
  if (!isFiniteNumber(value)) return fallback;
  return clamp(value, MIN_WEIGHT, MAX_WEIGHT);
}

// Unknown keys are ignored deliberately; the caller receives them as evidence
// rather than having them silently influence a score.
export function normalizeWeights(value = {}, {base = DEFAULT_VALUATION_WEIGHTS} = {}) {
  const input = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const weights = {};
  const ignored = [];
  const invalid = [];
  for (const key of YIELD_KEYS) {
    const candidate = input[key] === undefined ? base[key] : input[key];
    if (!isFiniteNumber(candidate)) {
      // Never substitute a working weight for NaN/Infinity: the caller must
      // see invalid so a top-level score cannot look successfully estimated.
      invalid.push(key);
      weights[key] = 0;
    } else {
      weights[key] = normalizeWeight(candidate, 0);
    }
  }
  for (const key of Object.keys(input)) if (!YIELD_KEYS.includes(key)) ignored.push(key);
  return Object.freeze({
    status: invalid.length ? 'invalid' : 'estimated',
    weights: Object.freeze(weights),
    ignored,
    invalid
  });
}

// Score a yield object (usually a delta or a per-turn flow).
// - missing keys contribute 0 but are reported in `missing`;
// - non-finite supplied values invalidate the score instead of becoming NaN;
// - requireAll turns any missing key into not-estimated.
export function scoreYields(yields, weightsInput = DEFAULT_VALUATION_WEIGHTS, {requireAll = false} = {}) {
  const normalized = weightsInput && weightsInput.weights ? weightsInput : normalizeWeights(weightsInput);
  const weights = normalized.weights;
  const values = yields && typeof yields === 'object' && !Array.isArray(yields) ? yields : null;
  if (!values) return Object.freeze({status: 'invalid', reason: 'yields-object-required', score: null, contributions: null, missing: [], invalid: []});
  if (normalized.status === 'invalid') {
    return Object.freeze({status: 'invalid', reason: 'invalid-weights', score: null, contributions: null, missing: [], invalid: Object.freeze(normalized.invalid || []), weights});
  }
  const contributions = {};
  const missing = [];
  const invalid = [];
  let total = 0;
  for (const key of YIELD_KEYS) {
    if (values[key] === undefined) {
      missing.push(key);
      contributions[key] = 0;
      continue;
    }
    if (!isFiniteNumber(values[key])) {
      invalid.push(key);
      contributions[key] = null;
      continue;
    }
    const contribution = values[key] * weights[key];
    if (!isFiniteNumber(contribution)) {
      invalid.push(key);
      contributions[key] = null;
      continue;
    }
    contributions[key] = contribution;
    total += contribution;
  }
  if (invalid.length) {
    return Object.freeze({status: 'invalid', reason: 'non-finite-yield-or-overflow', score: null, contributions: Object.freeze(contributions), missing: Object.freeze(missing), invalid: Object.freeze(invalid), weights});
  }
  if (!isFiniteNumber(total)) {
    return Object.freeze({status: 'invalid', reason: 'score-overflow', score: null, contributions: Object.freeze(contributions), missing: Object.freeze(missing), invalid: Object.freeze(['total']), weights});
  }
  if (requireAll && missing.length) {
    return Object.freeze({status: 'not-estimated', reason: 'missing-yields', score: null, contributions: Object.freeze(contributions), missing: Object.freeze(missing), invalid: Object.freeze([]), weights});
  }
  return Object.freeze({
    status: missing.length ? 'partial' : 'estimated',
    score: total,
    contributions: Object.freeze(contributions),
    missing: Object.freeze(missing),
    invalid: Object.freeze([]),
    weights,
    evidence: Object.freeze({weights: Object.freeze({...weights}), yields: Object.freeze({...values})})
  });
}

export function scoreYieldsDelta(before, after, weights, options = {}) {
  const b = before && typeof before === 'object' ? before : {};
  const a = after && typeof after === 'object' ? after : {};
  const delta = {};
  for (const key of YIELD_KEYS) {
    if (a[key] === undefined && b[key] === undefined) continue;
    if (!isFiniteNumber(a[key]) || !isFiniteNumber(b[key])) {
      return Object.freeze({status: 'invalid', reason: 'non-finite-yield', score: null, delta: null});
    }
    delta[key] = a[key] - b[key];
  }
  const scored = scoreYields(delta, weights, options);
  return Object.freeze({...scored, delta: Object.freeze(delta)});
}
